package scan

// Tier says how safe a folder is to delete.
type Tier int

const (
	// Build output: regenerated by the next build.
	Build Tier = iota
	// Deps: reinstallable dependencies; needs npm install / pod install / ... afterwards.
	Deps
)

type folder struct {
	name string
	tier Tier
}

type rule struct {
	typ     string
	folders []folder
}

var (
	gradleRoot   = rule{"gradle", []folder{{"build", Build}, {".gradle", Build}, {".kotlin", Build}}}
	gradleModule = rule{"gradle", []folder{{"build", Build}, {".cxx", Build}}}
	python       = rule{"python", []folder{
		{".pytest_cache", Build}, {".mypy_cache", Build}, {".ruff_cache", Build},
		{".venv", Deps}, {"venv", Deps},
	}}

	// fileRules: a marker file -> folders next to it that may be deleted.
	// A folder is only deleted when its marker sits next to it, never by name alone.
	fileRules = map[string]rule{
		"settings.gradle":     gradleRoot,
		"settings.gradle.kts": gradleRoot,
		"build.gradle":        gradleModule,
		"build.gradle.kts":    gradleModule,
		"pubspec.yaml":        {"flutter", []folder{{"build", Build}, {".dart_tool", Build}}},
		// dist/ and build/ are left alone for node: some projects commit them.
		"package.json": {"node", []folder{
			{".next", Build}, {".nuxt", Build}, {".turbo", Build},
			{".svelte-kit", Build}, {".parcel-cache", Build},
			{"node_modules", Deps},
		}},
		"Podfile":          {"cocoapods", []folder{{"build", Build}, {"Pods", Deps}}},
		"Package.swift":    {"swift", []folder{{".build", Build}}},
		"Cargo.toml":       {"rust", []folder{{"target", Build}}},
		"pom.xml":          {"maven", []folder{{"target", Build}}},
		"composer.json":    {"php", []folder{{"vendor", Deps}}},
		"pyproject.toml":   python,
		"requirements.txt": python,
	}

	// xcodeRule applies next to a folder ending in .xcodeproj.
	xcodeRule = rule{"xcode", []folder{{"build", Build}, {"DerivedData", Build}}}

	// prune: never walk into these. They are outputs or deps themselves,
	// or huge folders that never hold projects.
	prune = map[string]bool{
		"node_modules": true, ".git": true, "build": true, ".gradle": true, ".kotlin": true,
		".cxx": true, "Pods": true, ".dart_tool": true, "DerivedData": true, "target": true,
		".build": true, "vendor": true, ".venv": true, "venv": true, ".next": true,
		".nuxt": true, ".turbo": true, ".svelte-kit": true, ".parcel-cache": true,
		"__pycache__": true, ".idea": true, ".pytest_cache": true, ".mypy_cache": true,
		".ruff_cache": true,
	}
)

// Types lists every project type, sorted.
func Types() []string {
	return []string{"cocoapods", "flutter", "gradle", "maven", "node", "php", "python", "rust", "swift", "xcode"}
}
